import zipfile, re
from xml.etree import ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

path = 'sales_data.xlsx'
z = zipfile.ZipFile(path)
print('=== ZIP ENTRIES ===')
for n in z.namelist():
    print(n)

def parse(part):
    return ET.fromstring(z.read(part))

wb = parse('xl/workbook.xml')
print('\n=== WORKBOOK SHEETS ===')
sheets = []
for sh in wb.find('m:sheets', NS):
    sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
print(sheets)

rels = parse('xl/_rels/workbook.xml.rels')
rid2target = {}
for rel in rels:
    rid2target[rel.get('Id')] = rel.get('Target')
print('\n=== RELS ===')
for rid, t in rid2target.items():
    print(rid, '->', t)

# shared strings
ss = []
if 'xl/sharedStrings.xml' in z.namelist():
    sst = parse('xl/sharedStrings.xml')
    for si in sst.find('m:sst', NS):
        texts = [t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')]
        ss.append(''.join(texts))
    print('\n=== SHARED STRINGS (%d) ===' % len(ss))
    for i, s in enumerate(ss):
        print(i, repr(s))

